  1	// One popup for an entry, read and written in the same rows. A row is text until it is clicked;
  2	// then it holds the control for its value - and it holds it **without changing shape**. A row
  3	// that grew a heading and a control beneath it moved every row under it and sent the eye hunting
  4	// for the field it had just tapped, which is the one thing a popup opened to type one word must
  5	// not do. So a row that can hold its control on one line does (the title, location, alerts and
  6	// participants are an input in the line, with the field's name as the placeholder), and a row
  7	// whose control cannot be a line opens that control in a small popup anchored to the row, which
  8	// is left exactly as it was (the when, the category, the repetition and the estimate).
  9	//
 10	// The rows hold a draft and nothing reaches the repo until the top row's disk, so one entry edit
 11	// is one commit and the x discards the lot. The disk appears only once the draft differs from
 12	// the file, which is the same comparison the discard prompt makes - one definition of changed,
 13	// so a disk cannot appear where the prompt would stay silent.
 14	//
 15	// Per-row write-through was rejected: the popup would hold a stale occurrence after the first
 16	// write, a saved date would move the file out from under it, and several saves queued offline
 17	// would write to one path more than once in a single tree.
 18	import {
 19	  isAllDay, todayKey, toInstant, wallParts, dowOf, partsOf, timeLabel, STAGES, pad, list,
 20	  createEntry, updateEntry, deleteEntry, saveOverride, skipOccurrence, createGroup, saveGroups
 21	} from './data.js';
 22	import { setKV } from '../shared/store.js';
 23	import { render } from '../shared/markdown.js';
 24	import {
 25	  S, $, el, icon, iconBtn, labelOf, longDayLabel, inkOn, openRowPop, STAGE_COLOR
 26	} from './ui.js';
 27	
 28	const splitList = v => String(v).split(/[,;\s]+/).map(s => s.trim()).filter(Boolean);
 29	
 30	// Keys the form owns: cleared from the file's data before collect() writes them back, so
 31	// anything else - exdate, rdate, status, a hand-added key - survives a save untouched.
 32	const FORM_KEYS = ['title', 'type', 'start', 'end', 'stage', 'important',
 33	  'estimate', 'group', 'location', 'recurrence', 'alerts', 'participants'];
 34	
 35	let D = null;        // the draft
 36	let active = null;   // the row holding an inline input: { key }
 37	let popped = null;   // the key whose anchored popup is open
 38	let justClosed = null;   // the key a dismissing tap just closed, so that tap cannot reopen it
 39	
 40	// ---- the fields behind the icons ------------------------------------------------------------
 41	
 42	// The order is the same on a task as on an event, so the row does not reshuffle when the type
 43	// changes - and the detail rows below follow it, which puts participants at the bottom.
 44	// `mode` is how the field is edited: `inline` puts its input in the row, `pop` opens it in a
 45	// popup anchored to the row, `block` is the body, which is neither.
 46	const FIELDS = [
 47	  { k: 'body', ic: 'lines', label: 'Details', empty: '', mode: 'block',
 48	    set: v => !!v.trim(), sum: v => v.trim().split('\n').find(Boolean) || '', ed: bodyEditor },
 49	  { k: 'group', ic: 'ball', label: 'Category', empty: '', mode: 'pop',
 50	    set: v => !!v, sum: v => labelOf(v), ed: groupPicker },
 51	  { k: 'recurrence', ic: 'repeat', label: 'Repeat', empty: '', mode: 'pop',
 52	    set: v => !!v, sum: v => ruleText(v), ed: recurrenceEditor },
 53	  { k: 'alerts', ic: 'bell', label: 'Alerts', empty: [], mode: 'inline',
 54	    set: v => v.length > 0, sum: v => v.map(alertText).join(', '), ed: alertsEditor },
 55	  { k: 'location', ic: 'pin', label: 'Location', empty: '', mode: 'inline',
 56	    set: v => !!v, sum: v => v, ed: textEditor('Location') },
 57	  { k: 'participants', ic: 'person', label: 'Participants', empty: [], mode: 'inline',
 58	    set: v => v.length > 0, sum: v => v.join(', '), ed: participantsEditor }
 59	];
 60	
 61	// The estimate has an editor but no place in D.v, so it reads and writes through these two
 62	// rather than reaching into D.v itself. The when has no place in D.v either and no stored value
 63	// at all - it is four parts of the draft - so its editor writes them itself.
 64	// `popClear` is the estimate alone: its row is an icon on the toggle row with no room for a
 65	// trashcan beside it, so the one place its popup differs from the other three is that it carries
 66	// the trashcan in its own head.
 67	const EST = { k: 'estimate', ic: 'glass', label: 'Estimate', empty: null, mode: 'pop',
 68	  popClear: true, set: v => !!v, sum: v => `${v}d`, ed: estimateEditor };
 69	const WHEN = { k: 'when', label: 'When', mode: 'pop', ed: whenEditor };
 70	const readField = f => f.k === 'estimate' ? D.estimate : D.v[f.k];
 71	const writeField = (f, v) => { if (f.k === 'estimate') D.estimate = v; else D.v[f.k] = v; };
 72	
 73	const alertText = n => n === 0 ? 'at start' : `${n} min before`;
 74	
 75	// Only the series carries the rule: an occurrence override must never rewrite it.
 76	const canRule = () => !D.occ || D.scope === 'series' || !D.occ.seriesId;
 77	
 78	// The scope pair governs the trashcan as well as the disk. `this` skips the one occurrence -
 79	// which is what the `skip this one` link beside the pair used to do - and `all` deletes the rule
 80	// file. One choice, read by both writes in the row it sits in.
 81	const skipping = () => !!D.occ && !!D.occ.seriesId && D.scope === 'occurrence';
 82	
 83	// ---- opening -------------------------------------------------------------------------------
 84	
 85	export function openNew(seed = {}) {
 86	  open(null, 'occurrence', seed);
 87	}
 88	
 89	// Every way in lands here: a grid, the day preview and a card on the board alike. There is one
 90	// popup, and it is both - the entry is shown as text and every value is edited in its own row.
 91	export function openEntry(occ) {
 92	  if (!occ) return;
 93	  open(occ, 'occurrence', {});
 94	}
 95	
 96	function open(occ, scope, seed) {
 97	  D = draft(occ, scope, seed);
 98	  D.clean = snapshot(D);
 99	  active = occ ? null : { key: 'title' };
100	  $('#popup').hidden = false;
101	  $('#f-msg').textContent = '';
102	  fillForm();
103	  focusRow();
104	}
105	
106	function draft(occ, scope, seed) {
107	  const series = occ && occ.seriesId && scope === 'series';
108	  const data = occ ? (series ? occ.seriesData : occ.data) : {};
109	  const body = occ ? (series ? occ.seriesBody : occ.body) : '';
110	  const start = String(data.start ?? '');
111	  const allDay = occ ? isAllDay(start) : !!seed.allDay;
112	  const day = occ ? '' : (seed.dayKey || todayKey());
113	  const hour = seed.hour == null ? 9 : seed.hour;
114	
115	  const [sd, st] = occ && !allDay ? wallParts(start) : [occ ? start.slice(0, 10) : day, `${pad(hour)}:00`];
116	  let ed = '', et = '';
117	  if (occ && data.end != null) [ed, et] = allDay ? [String(data.end).slice(0, 10), ''] : wallParts(String(data.end));
118	  else if (!occ && !allDay) [ed, et] = [day, `${pad(Math.min(23, hour + 1))}:00`];
119	
120	  return {
121	    occ, scope, base: data,
122	    type: occ ? (data.type === 'task' ? 'task' : 'event') : (seed.type || 'event'),
123	    stage: occ ? (occ.stage || 'todo') : (seed.stage || 'todo'),
124	    important: occ ? occ.important : false,
125	    estimate: occ ? (occ.estimate ?? null) : 1,
126	    title: occ ? String(data.title ?? '') : '',
127	    allDay, startDate: sd, startTime: allDay ? '' : st, endDate: ed, endTime: allDay ? '' : et,
128	    v: {
129	      recurrence: occ && (series || !occ.seriesId) ? String(data.recurrence ?? '') : '',
130	      group: String(data.group ?? ''),
131	      location: String(data.location ?? ''),
132	      alerts: list(data.alerts).map(Number).filter(Number.isFinite),
133	      participants: list(data.participants).map(String),
134	      body: body ?? ''
135	    }
136	  };
137	}
138	
139	// What a discard would lose, and - the same question - what the disk has to write: the draft's
140	// editable parts against the baseline taken when the popup opened. One comparison, so the disk
141	// cannot appear where the prompt would stay silent.
142	const snapshot = d => JSON.stringify([d.type, d.stage, d.important, d.estimate, d.title,
143	  d.allDay, d.startDate, d.startTime, d.endDate, d.endTime, d.v]);
144	
145	// A new entry always has something to write, there being no file yet; the disk is disabled until
146	// it has a title instead.
147	const dirty = () => !!D && (!D.occ || snapshot(D) !== D.clean);
148	
149	// ---- leaving -------------------------------------------------------------------------------
150	
151	// Leaving a popup that holds unsaved changes asks first - the x, the backdrop and Escape are one
152	// way out and ask one question. A row's own x is not guarded and has nothing to guard: it closes
153	// a row and keeps what is in it.
154	function closePopup() {
155	  if (D && S.prefs.confirmDiscard && snapshot(D) !== D.clean) {
156	    $('#ask-never').checked = false;
157	    $('#ask').hidden = false;
158	    return;
159	  }
160	  discard();
161	}
162	
163	function discard() {
164	  $('#ask').hidden = true;
165	  $('#popup').hidden = true;
166	  $('#fpop').hidden = true;
167	  active = null;
168	  popped = null;
169	  D = null;
170	}
171	
172	// Escape unwinds the one layer there is: a field's popup, which is a real overlay with an x of
173	// its own, swallows it so that Escape inside a field does not throw away the edit the field is
174	// part of. An **inline row does not** - it is the row in its editing state, not a layer over
175	// anything, and leaving it loses nothing, so Escape there keeps meaning "leave the popup". A new
176	// entry opens with its title row already an input, and making that swallow the first Escape would
177	// have cost two presses to leave the commonest popup in the app.
178	export function escapeEntry() {
179	  if (popped !== null) closeFieldPop();
180	  else closePopup();
181	}
182	
183	$('#ask-keep').addEventListener('click', () => { $('#ask').hidden = true; });
184	$('#ask').addEventListener('click', e => { if (e.target === $('#ask')) $('#ask').hidden = true; });
185	$('#ask-discard').addEventListener('click', async () => {
186	  // Ticking it silences the prompt on this device for good; the panel's settings row is what
187	  // puts it back, because nothing in Mine may be switched off from a place that cannot switch
188	  // it back on.
189	  if ($('#ask-never').checked) {
190	    S.prefs.confirmDiscard = false;
191	    await setKV('calendar.confirmDiscard', false);
192	  }
193	  discard();
194	});
195	
196	$('#popup').addEventListener('click', e => {
197	  if (justClosed === null && e.target === $('#popup')) closePopup();
198	});
199	
200	// Enter in a row's editor closes the row; it does not submit. The editor has been writing into
201	// the draft all along, so there is nothing for Enter to accept - and the key that ends a word
202	// must not also commit the entry and close the popup. Shift+Enter is handed straight back to the
203	// browser, whose own default is what puts a new line in the body's textarea, which is the whole
204	// reason that case is a bail-out and not code. `#fpop` lives outside `#f-rows`, so a field's own
205	// popup is untouched: it still closes by its x or by Escape.
206	$('#f-rows').addEventListener('keydown', e => {
207	  if (e.key !== 'Enter' || e.shiftKey) return;
208	  if (!/^(INPUT|TEXTAREA)$/.test(e.target.tagName)) return;   // a row's own buttons still work
209	  e.preventDefault();
210	  closeRow();
211	});
212	
213	// ---- rows ----------------------------------------------------------------------------------
214	// A row is the icon, then the value - no field name beside it. Clicking it opens its control
215	// without moving the row: an input in the line, or a popup anchored under it.
216	//
217	// An open editor writes into the draft as it is typed, which is what lets the disk appear the
218	// moment something differs from the file without the row being re-rendered under the cursor -
219	// and it is what makes closing a row keep what was typed without a save to press.
220	
221	function fillForm() {
222	  iconRow();
223	  $('#f-rows').replaceChildren(titleRow(), whenRow(), flagsRow(), ...fieldRows(), bodyBlock());
224	}
225	
226	const is = key => !!active && active.key === key;
227	
228	// Only one row is open at a time, and an inline row and a field popup are never both open:
229	// opening either simply closes the other, whose value is already in the draft.
230	function openRow(key) {
231	  closeFieldPop(false);
232	  active = { key };
233	  fillForm();
234	  focusRow();
235	}
236	
237	// Closing a row keeps what is in it: the editor has been writing into the draft all along, so
238	// there is nothing to accept. Clearing the field is the trashcan beside the x, and undoing the
239	// edit of a whole entry is the popup's own x.
240	function closeRow() {
241	  if (!active) return;
242	  active = null;
243	  fillForm();
244	}
245	
246	// A tap that is the whole edit - the type pair, the toggle row, the scope pair - changes the
247	// draft and redraws, which also closes whatever row was open, whose value is already in the
248	// draft. Separate from closeRow because these redraw whether or not a row was open.
249	function redraw() {
250	  active = null;
251	  closeFieldPop(false);
252	  fillForm();
253	}
254	
255	// ---- a field's own popup -------------------------------------------------------------------
256	// Anchored to the row that opened it, which keeps its icon, its value and its trashcan: nothing
257	// about the row moves, which is the whole point. The four fields behind one are those whose
258	// control cannot be a single line - four date and time boxes, a list of categories, a rule and
259	// its end condition, a number with a unit.
260	//
261	// It carries **no scrim**, unlike every other overlay in the calendar. A scrim would make the tap
262	// that dismisses it stop there, so moving from one field to the next would take two taps; without
263	// one the tap reaches the row it landed on and opens it. `justClosed` is what keeps that tap from
264	// reopening the field it has just closed.
265	
266	function openFieldPop(f) {
267	  closeRow();
268	  popped = f.k;
269	  const ed = f.ed(f.k === 'when' ? null : readField(f));
270	  if (f.k !== 'when') live(ed.node, () => writeField(f, ed.read()));
271	  $('#fpop-title').textContent = f.label;
272	  const head = $('#fpop-title').parentElement;
273	  head.querySelector('.ib.bad')?.remove();
274	  if (f.popClear && f.set(readField(f))) head.insertBefore(clearBtn(f), $('#fpop-close'));
275	  $('#fpop-body').replaceChildren(ed.node);
276	  // The anchor is looked up rather than passed in: on a dismissing tap the capture-phase
277	  // listener below re-renders the rows before the row's handler calls this, so a node passed in
278	  // from that handler is already detached and measures as zero.
279	  openRowPop($('#fpop'), $(`#f-rows [data-field="${f.k}"]`));
280	  requestAnimationFrame(() => $('#fpop').querySelector('input, select, textarea')?.focus());
281	}
282	
283	function closeFieldPop(render = true) {
284	  if (popped === null) return;
285	  popped = null;
286	  $('#fpop').hidden = true;
287	  if (render) fillForm();            // the row reads the value the popup has just changed
288	}
289	
290	$('#fpop-close').addEventListener('click', () => closeFieldPop());
291	
292	// Capture, so this runs before the row's own click handler: the popup closes and the same tap
293	// then opens whatever it hit.
294	addEventListener('click', e => {
295	  if (popped === null || $('#fpop').contains(e.target)) return;
296	  justClosed = popped;
297	  closeFieldPop();
298	  setTimeout(() => { justClosed = null; }, 0);
299	}, true);
300	
301	// One way in for every row: the popup for the four whose control cannot be a line, the row itself
302	// for the three that can.
303	function openField(f) {
304	  if (justClosed === f.k) return;    // the tap that closed it must not reopen it
305	  if (f.mode === 'pop') openFieldPop(f);
306	  else openRow(f.k);
307	}
308	
309	const focusRow = () =>
310	  requestAnimationFrame(() => $('#f-rows').querySelector('input, select, textarea')?.focus());
311	
312	// The disk's presence is the only thing that changes while a row is being typed into, so it is
313	// redrawn on its own - re-rendering the row would take the cursor with it.
314	const syncDisk = () => iconRow();
315	
316	function live(node, apply) {
317	  for (const ev of ['input', 'change'])
318	    node.addEventListener(ev, () => { apply(); syncDisk(); });
319	}
320	
321	// A ticked square and a calendar page choose the type on a new entry; on one that exists the
322	// type is a marker, shown and not pressable. On a repeating entry the scope pair follows it.
323	// Then the trashcan, the disk once there is something to save, and the x - rightmost in every
324	// popup in Mine.
325	function iconRow() {
326	  const kids = [];
327	  if (D.occ) {
328	    const mark = el('span', 'ib on');
329	    mark.title = D.type === 'task' ? 'Task' : 'Event';
330	    mark.setAttribute('role', 'img');
331	    mark.setAttribute('aria-label', mark.title);
332	    mark.append(icon(D.type === 'task' ? 'check' : 'cal'));
333	    kids.push(mark);
334	  } else for (const [t, ic, label] of [['task', 'check', 'Task'], ['event', 'cal', 'Event']]) {
335	    const b = iconBtn(ic, label, D.type === t ? 'on' : '');
336	    b.setAttribute('aria-pressed', String(D.type === t));
337	    b.addEventListener('click', () => { D.type = t; redraw(); });
338	    kids.push(b);
339	  }
340	  if (D.occ && D.occ.seriesId) kids.push(scopePair());
341	  kids.push(el('span', 'spacer'));
342	
343	  if (D.occ) {
344	    const t = iconBtn('trash', !D.occ.seriesId ? 'Delete'
345	      : skipping() ? 'Skip this occurrence' : 'Delete every occurrence', 'bad');
346	    t.addEventListener('click', () => removeEntry(D.occ));
347	    kids.push(t);
348	  }
349	  if (dirty()) {
350	    const disk = iconBtn('disk', 'Save', 'save');
351	    disk.type = 'submit';
352	    disk.disabled = !D.title.trim();
353	    kids.push(disk);
354	  }
355	  const x = iconBtn('x', 'Close');
356	  x.addEventListener('click', closePopup);
357	  kids.push(x);
358	
359	  $('#f-icons').replaceChildren(...kids);
360	}
361	
362	// A repeating entry's one choice about one write, in the row with the two controls it governs:
363	// `this` writes an override for this occurrence and skips it on the trashcan, `all` rewrites the
364	// rule file and deletes it. It reads `this` and `all` and not the noun, because the noun is a
365	// task on one entry and an event on the next while the marker beside it already says which.
366	//
367	// Switching it rebuilds the draft from the other file, so the baseline a discard is measured
368	// against has to be retaken with it - left behind it reads as changed, which puts a disk in the
369	// top row of a popup nobody has edited.
370	function scopePair() {
371	  const group = el('div', 'btngroup');
372	  group.setAttribute('role', 'radiogroup');
373	  group.setAttribute('aria-label', 'Edit scope');
374	  for (const [v, text, aria] of [['occurrence', 'this', 'This occurrence'],
375	    ['series', 'all', 'All occurrences']]) {
376	    const b = el('button', 'seg', text);
377	    b.type = 'button';
378	    b.setAttribute('aria-label', aria);
379	    b.setAttribute('aria-pressed', String(D.scope === v));
380	    b.addEventListener('click', () => {
381	      D = draft(D.occ, v, {});
382	      D.clean = snapshot(D);
383	      redraw();
384	    });
385	    group.append(b);
386	  }
387	  return group;
388	}
389	
390	// The title is a row too: text until clicked, then an input in the same line at the same size.
391	// It is the one row with neither a trashcan nor an x - an entry must have a title, so there is
392	// nothing to clear, and the popup's own x, which discards the whole edit, is a thumb's width
393	// above this line. It closes on Escape, or by opening any other row.
394	function titleRow() {
395	  const row = el('div', `frow first${is('title') ? ' in' : ''}`);
396	  row.dataset.field = 'title';
397	  if (is('title')) {
398	    const i = el('input', 'title-in');
399	    i.value = D.title;
400	    i.placeholder = 'Title';
401	    live(i, () => { D.title = i.value; });
402	    row.append(i);
403	    return row;
404	  }
405	  row.append(tap(D.title || 'Untitled', !D.title, 'ttap',
406	    () => openRow('title'),
407	    `Title${D.title ? `: ${D.title}` : ''}`));
408	  return row;
409	}
410	
411	// The when: one row reading the day and the times, opening the four inputs in a popup under it.
412	// Four input boxes at the top of a popup opened to find out what day something is on was the form
413	// at its least readable, and four of them cannot be a line, so they are the clearest case for the
414	// popup: the row goes on reading the day while they are open.
415	function whenRow() {
416	  const row = el('div', 'frow');
417	  row.dataset.field = 'when';
418	  row.append(tap(whenText(), false, 'wtap', () => openField(WHEN), `When: ${whenText()}`));
419	  return row;
420	}
421	
422	function whenText() {
423	  const day = D.startDate ? longDayLabel(D.startDate) : 'no date';
424	  const when = D.allDay ? 'all-day'
425	    : D.endTime && D.endTime !== D.startTime ? `${D.startTime}–${D.endTime}`
426	      : D.startTime || '';
427	  return when ? `${day} · ${when}` : day;
428	}
429	
430	// Five of the six fields are rows; the sixth is the body, at the foot. They are in the canonical
431	// order whether they are set or not. They used to be sorted set-first, which moved a row the
432	// moment it was filled - so the field just typed into was no longer where it had just been looked
433	// for, which is the same complaint the rows that grew answered.
434	function fieldRows() {
435	  return FIELDS
436	    .filter(f => f.k !== 'body' && (f.k !== 'recurrence' || canRule()))
437	    .map(f => f.mode === 'inline' && is(f.k) ? inlineRow(f) : closedRow(f));
438	}
439	
440	function closedRow(f) {
441	  const row = el('div', 'frow');
442	  row.dataset.field = f.k;
443	  const set = f.set(readField(f));
444	  row.append(icon(f.ic));
445	  row.append(tap(set ? f.sum(readField(f)) : f.label, !set, '',
446	    () => openField(f),
447	    `${f.label}${set ? `: ${f.sum(readField(f))}` : ''}`));
448	  if (set) row.append(clearBtn(f));
449	  return row;
450	}
451	
452	// An inline row: the input takes the line the value was on, at the same height, with the trashcan
453	// and the x where the closed row's trashcan already is. The field's name is the input's
454	// placeholder rather than a heading above it, because a heading was the line the row grew by and
455	// it named what the icon beside it already said.
456	function inlineRow(f) {
457	  const row = el('div', 'frow in');
458	  row.dataset.field = f.k;
459	  const ed = f.ed(readField(f));
460	  live(ed.node, () => writeField(f, ed.read()));
461	  const x = iconBtn('x', 'Close this field');
462	  x.addEventListener('click', closeRow);
463	  row.append(icon(f.ic), ed.node, clearBtn(f), x);
464	  return row;
465	}
466	
467	// The row carries its field's key, and the button that opens it says the field's name even when
468	// the row shows only a value - a bell with `15 min before` beside it needs the name read out.
469	function tap(text, unset, cls, onClick, aria) {
470	  const b = el('button', ['ftap', cls, unset ? 'unset' : ''].filter(Boolean).join(' '), text);
471	  b.type = 'button';
472	  b.setAttribute('aria-label', aria);
473	  b.addEventListener('click', onClick);
474	  return b;
475	}
476	
477	// Clearing a field is its row's own trashcan, and it clears the draft - nothing here writes.
478	// Clicking it must not also activate the row: the field is cleared and no input appears.
479	function clearBtn(f) {
480	  const b = iconBtn('trash', `Clear ${f.label.toLowerCase()}`, 'bad');
481	  b.addEventListener('click', e => {
