// The keyboard path, the end half, all-day, and back.
import { ev, viewport, goto, seed, sleep, send } from '/home/max/ws/mine/test/cdp.mjs';

const key = async (k, text) => {
  const code = /\d/.test(k) ? `Digit${k}` : k === 'Enter' ? 'Enter' : k;
  const p = { key: k, code, windowsVirtualKeyCode: k === 'Enter' ? 13 : k.charCodeAt(0),
    nativeVirtualKeyCode: k === 'Enter' ? 13 : k.charCodeAt(0) };
  await send('Input.dispatchKeyEvent', { ...p, type: 'keyDown', text: text ?? k });
  await send('Input.dispatchKeyEvent', { ...p, type: 'keyUp' });
  await sleep(250);
};
const state = async what => {
  const r = await ev(`(() => {
    const row = document.querySelector('#f-rows [data-field="when"]');
    const pop = document.querySelector('#fpop');
    const i = pop.querySelector('input');
    return { row: [...row.querySelectorAll('.ftap, .wdash')].map(n => n.textContent),
      title: document.querySelector('#fpop-title').textContent,
      open: !pop.hidden, input: i ? [i.placeholder, i.value] : null,
      kind: pop.querySelector('.hgrid') ? 'hours' : pop.querySelector('.mgrid') ? 'quarters'
        : pop.querySelector('.pick-body') ? 'days' : 'none' };
  })()`);
  console.log(what, JSON.stringify(r));
  return r;
};

