await ev(`document.querySelector('#f-rows [data-field="when"] .ftap').click()`);
await sleep(350);
await key('2', '2');
await state('digit typed');
await ev(`const i = document.querySelector('#fpop input'); i.value = '0312'; i.focus();`);
await key('Enter');
await state('enter on 0312 (no year -> the shown month\\'s)');
await ev(`const i = document.querySelector('#fpop input'); i.value = '845'; i.focus();`);
await key('Enter');
await state('enter on 845 -> end date, as a picker again');
await ev(`document.querySelector('#fpop-close').click()`);
await sleep(300);
await state('left mid-flow, keeping what it wrote');

// --- a refused date goes back to the draft
await ev(`document.querySelector('#f-rows [data-field="when"] .ftap').click()`);
await sleep(300);
await key('9', '9');
await ev(`const i = document.querySelector('#fpop input'); i.value = '31.02.2026'; i.focus();`);
await key('Enter');
await state('31 February refused');
await ev(`document.querySelector('#fpop-close').click()`);
await sleep(250);

