await sleep(350);
await state('end half');
// --- back from the end date is the start time
await ev(`document.querySelector('.pop-head .ib.back').click()`);
await sleep(300);
await state('back');
await ev(`document.querySelector('#fpop-close').click()`);
await sleep(250);

