await ev(`[...document.querySelectorAll('#f-rows .flags .ib')][0].click()`);
await sleep(300);
await state('24h on');
await ev(`document.querySelector('#f-rows [data-field="when"] .ftap').click()`);
await sleep(300);
await state('all-day: start date');
await ev(`[...document.querySelectorAll('#fpop .pick-body .pk')]
  .find(b => b.textContent === '12' && !b.classList.contains('out')).click()`);
await sleep(350);
await state('all-day: straight to the end date');
await ev(`[...document.querySelectorAll('#fpop .pick-body .pk')]
  .find(b => b.textContent === '5' && !b.classList.contains('out')).click()`);
await sleep(350);
await state('an end before the start clamps, and the flow ends');
process.exit(0);

