// The quick row, the chevron, the alert list and the repetition's two steps.
import { ev, viewport, goto, seed, sleep, send, SHOT } from '/home/max/ws/mine/test/cdp.mjs';

const shot = async name => {
  if (!SHOT) return;
  const s = await send('Page.captureScreenshot', { format: 'png' });
  (await import('fs')).writeFileSync(`${SHOT}/${name}.png`, Buffer.from(s.data, 'base64'));
};
const look = async what => {
  const r = await ev(`(() => {
    const bar = document.querySelector('#f-rows .quick');
    const p = document.querySelector('#fpop');
    return {
      icons: bar ? [...bar.querySelectorAll('.ib')].map(b => b.getAttribute('aria-label')) : null,
      lines: [...document.querySelectorAll('#f-rows .frow')].map(r =>
        r.classList.contains('chips') ? 'chips' : r.dataset.field),
      pop: p.hidden ? null : {
        title: document.querySelector('#fpop-title').textContent,
        rows: [...p.querySelectorAll('.gpick')].map(b =>
          (b.disabled ? '[locked] ' : '') + b.textContent + (b.classList.contains('on') ? ' *' : '')),
        kind: p.querySelector('.hgrid') ? 'hours' : p.querySelector('.pick-body') ? 'days'
          : p.querySelector('input') ? 'input:' + p.querySelector('input').type : 'list'
      },
      over: document.documentElement.scrollWidth - document.documentElement.clientWidth
    };
  })()`);
  console.log(what, JSON.stringify(r));
  return r;
};
const click = async sel => { await ev(`document.querySelector('${sel}').click()`); await sleep(350); };

await viewport(360);
await goto('/calendar/');
await seed('calendar', { 'calendar.weekStart': 1 });
await goto('/calendar/');
await ev(`[...document.querySelectorAll('.eline')].find(l => /Sprint planning/.test(l.textContent)).click()`);
await sleep(500);
await look('an event, collapsed');
await shot('quick-collapsed');

await click('#f-rows .quick [data-field="alerts"]');
await look('the alert list');
await shot('quick-alerts');
await ev(`[...document.querySelectorAll('#fpop .gpick')].find(b => /15 min/.test(b.textContent)).click()`);
await sleep(350);
await look('15 min picked');

await click('#f-rows .quick [data-field="recurrence"]');
await look('the repetition list');
await shot('quick-repeat');
await ev(`[...document.querySelectorAll('#fpop .gpick')].find(b => b.textContent === 'weekly').click()`);
await sleep(350);
await look('after weekly: the end condition');
await ev(`[...document.querySelectorAll('#fpop .gpick')].find(b => /on a date/.test(b.textContent)).click()`);
await sleep(350);
await look('on a date: the picker');
await shot('quick-until');
await ev(`[...document.querySelectorAll('#fpop .pick-body .pk')]
  .find(b => b.textContent === '28' && !b.classList.contains('out')).click()`);
await sleep(350);
await look('picked, and shut');

await click('#f-rows .quick .more');
await look('expanded');
await shot('quick-expanded');

// the repetition again, from its line this time
await click('#f-rows .frow[data-field="recurrence"] .ftap');
await look('from the line');
await ev(`document.querySelector('#fpop-close').click()`);
await sleep(250);

// a task, for the stage line
await ev(`document.querySelector('#f-rows .quick .ib').click()`);   // all-day, to see the chips
await sleep(300);
await look('all-day on');
await shot('quick-expanded-task');
process.exit(0);

